effect.shader:
void main() {
    vec4 color = texture(inputImg, acScreenNorm);

    // Luma perceptual (coeficientes ITU-R BT.601). Usar a média simples dos
    // canais daria peso igual ao azul, que o olho enxerga bem menos — e o
    // resultado ficaria com o mapeamento errado em céu e em pele.
    float luma = dot(color.rgb, vec3(0.299, 0.587, 0.114));

    vec3 mapped;
    if (luma < midPoint) {
        mapped = mix(shadows.rgb, midtones.rgb, luma / midPoint);
    } else {
        mapped = mix(midtones.rgb, highlights.rgb, (luma - midPoint) / (1.0 - midPoint));
    }

    fragColor = vec4(clamp(mapped, 0.0, 1.0), color.a);
}
